import type { CR, Snapshot } from '../schema/types';

export type Family = 'G1' | 'G2' | 'G3' | 'G4' | 'G5' | 'G6';
export type Severity = 'block' | 'warn';

export type GuardrailFinding = {
  family: Family;
  rule: string;
  step_index: number | null;
  severity: Severity;
  message: string;
  evidence: unknown;
};

/** Per-step facts from a rehearsal. Index matches cr.steps. */
export type RehearsalStep = {
  ok?: boolean;
  /** Rows affected by the step (command tag count). Not collected by the Actor yet. */
  rows_affected?: number;
  /** WAL bytes generated by the step (pg_current_wal_lsn delta). Not collected yet. */
  wal_bytes?: number;
  /** Read-back of a config step (collected by the Actor). */
  setting_primary?: string;
  setting_standby?: string;
};

/**
 * Everything is optional. A rule whose input is absent returns no finding and
 * reports missing_context in the evaluations; rules never guess.
 */
export type GuardrailContext = {
  baseline?: Snapshot;
  rehearsal?: Snapshot;
  steps?: RehearsalStep[];
  /** Relation size in bytes, keyed by bare or schema-qualified name. */
  relation_sizes?: Record<string, number>;
  /** Estimated row count per relation (pg_class.reltuples). */
  relation_rows?: Record<string, number>;
  /** relfilenode per relation before and after rehearsal. */
  relfilenodes?: { before: Record<string, number>; after: Record<string, number> };
  /** pg_depend dependents per object name (tables, columns as table.col, functions, types). */
  dependents?: Record<string, string[]>;
  /** pg_settings.context per GUC name. */
  setting_context?: Record<string, string>;
  /** pg_settings.unit per GUC name, used to compare bare read-back numbers. */
  setting_units?: Record<string, string>;
  /** pg_settings.pending_restart per GUC after rehearsal. */
  pending_restart?: Record<string, boolean>;
  /** Function volatility (i, s, v) by function name, for column defaults. */
  function_volatility?: Record<string, 'i' | 's' | 'v'>;
  /** Column types before the CR, keyed by table.column. */
  column_types?: Record<string, string>;
  /** Partitions left in detach-pending state after rehearsal (pg_inherits.inhdetachpending). */
  detach_pending?: string[];
  /** View names before and after rehearsal. */
  views?: { before: string[]; after: string[] };
  /** Index of the last CR step the rehearsal executed. Default: the last step. */
  rehearsed_through_step?: number;
  /** Workload shape SQL texts keyed by shape id (q01). */
  workload_texts?: Record<string, string>;
  /** pg_stat_statements query texts. */
  pgss_texts?: string[];
  /** View and function definitions keyed by object name. */
  definitions?: Record<string, string>;
  /** Thresholds and host facts. */
  rewrite_block_bytes?: number;
  wal_budget_bytes?: number;
  ram_bytes?: number;
  max_connections?: number;
};

export type EvalStatus = "ran" | "missing_context" | "not_applicable";
/** Whether a rule ran, and which context fields it needed. */
export type RuleEvaluation = { rule: string; needs: string[]; missing: string[]; status: EvalStatus; can_block: boolean };
/** clear: all rules evaluated, none blocked. unevaluated: no block, but a blocking-capable rule lacked its context. */
export type Residual = "clear" | "blocked" | "unevaluated";

/** Collects per-rule evaluation status. Precedence: missing_context > ran > not_applicable. */
export class Evals {
  readonly map = new Map<string, RuleEvaluation>();
  declare(rule: string, needs: string[] = [], canBlock = true): void {
    if (!this.map.has(rule)) this.map.set(rule, { rule, needs, missing: [], status: "not_applicable", can_block: canBlock });
  }
  ran(rule: string): void {
    const e = this.get(rule);
    if (e.status === "not_applicable") e.status = "ran";
  }
  /** Mark the rule applicable; returns true when every field is present (the rule ran). */
  need(rule: string, fields: Record<string, boolean>): boolean {
    const e = this.get(rule);
    const missing = Object.entries(fields).filter(([, ok]) => !ok).map(([k]) => k);
    if (!missing.length) { this.ran(rule); return true; }
    e.status = "missing_context";
    for (const m of missing) if (!e.missing.includes(m)) e.missing.push(m);
    return false;
  }
  private get(rule: string): RuleEvaluation {
    if (!this.map.has(rule)) this.declare(rule);
    return this.map.get(rule)!;
  }
  list(): RuleEvaluation[] { return [...this.map.values()]; }
}

export type GuardrailRule = (cr: CR, ctx: GuardrailContext, ev?: Evals) => GuardrailFinding[];
export type GuardrailReport = { findings: GuardrailFinding[]; residual: Residual; evaluations: RuleEvaluation[] };
